#!/usr/bin/env bash
# =============================================================================
#  HomeHub - Installer fuer Proxmox VE (unprivilegierter LXC-Container)
#  Aufruf auf dem Proxmox-Host als root:   bash homehub-install.sh
#  Aktualisieren (Daten bleiben):          bash homehub-install.sh --update <CTID>
#  Hilfe:                                  bash homehub-install.sh --help
#  Alle Fragen lassen sich per Umgebungsvariable HH_<NAME> vorbelegen
#  (z. B. HH_CTID, HH_IP, HH_GW). Mit HH_YES=1 werden Vorgaben ohne Nachfrage genutzt.
# =============================================================================
set -Eeuo pipefail

PORT=8080
LOG="/tmp/homehub-install-$$.log"
: > "$LOG"; chmod 600 "$LOG"
CREATED=0; DONE=0; CTID=""; TMPD=""; ERRLINE=""
PVE_CFG_DIR="${PVE_CFG_DIR:-/etc/pve/nodes}"

if [ -t 1 ]; then B=$'\e[1m'; G=$'\e[32m'; Y=$'\e[33m'; R=$'\e[31m'; N=$'\e[0m'; else B=""; G=""; Y=""; R=""; N=""; fi
msg()  { printf '%s\n' "${B}==>${N} $*"; }
ok()   { printf '%s\n' "  ${G}OK${N}  $*"; }
warn() { printf '%s\n' "  ${Y}Hinweis:${N} $*" >&2; }
die()  { printf '%s\n' "${R}Fehler:${N} $*" >&2; exit 1; }

usage() {
cat <<EOF
HomeHub-Installer fuer Proxmox VE

  bash homehub-install.sh               Neuen Container interaktiv anlegen
  bash homehub-install.sh --update ID   Portal-Dateien im Container ID erneuern (Daten bleiben)
  bash homehub-install.sh --help        Diese Hilfe

Vorbelegung ohne Nachfrage (Beispiele):
  HH_CTID HH_HOSTNAME HH_STORAGE HH_DISK HH_RAM HH_CORES HH_BRIDGE HH_VLAN
  HH_IP HH_NETMASK HH_GW HH_DNS HH_ADMIN HH_ADMIN_PASS HH_PUBLIC_URL HH_PROXY_IP
  HH_UP_JELLYFIN HH_UP_PAPERLESS HH_UP_VAULTWARDEN HH_UP_HAUSAI HH_UP_RETROHUB
  HH_KNX_GW HH_KNX_PORT HH_TEMPLATE (z. B. debian-13-standard_13.6-1_amd64.tar.zst) HH_YES=1
EOF
}

trap 'ERRLINE=$LINENO' ERR
on_exit() {
  local code=$?
  trap - ERR EXIT
  if [ "$code" -ne 0 ] && [ "$DONE" = 0 ]; then
    if [ -n "$ERRLINE" ]; then echo >&2; echo "${R}Unerwarteter Fehler (Code $code, Zeile $ERRLINE).${N}" >&2; fi
    if [ -s "$LOG" ] && { [ -n "$ERRLINE" ] || [ "$CREATED" = 1 ]; }; then echo "Letzte Zeilen aus dem Protokoll ($LOG):" >&2; tail -n 12 "$LOG" >&2 || true; fi
    if [ "$CREATED" = 1 ] && [ -n "$CTID" ]; then
      if [ -t 0 ] && [ "${HH_YES:-0}" != 1 ]; then
        read -r -p "Den halb fertigen Container $CTID jetzt entfernen? [J/n] " a || a=n
        case "${a:-J}" in
          [jJyY]*|"") pct stop "$CTID" >/dev/null 2>&1 || true
                     if pct destroy "$CTID" --purge >/dev/null 2>&1; then echo "Container $CTID entfernt." >&2; else echo "Entfernen fehlgeschlagen: pct destroy $CTID --purge" >&2; fi;;
        esac
      else
        echo "Container $CTID bleibt zur Fehlersuche bestehen (Entfernen: pct destroy $CTID --purge)." >&2
      fi
    fi
  fi
  [ -n "$TMPD" ] && rm -rf "$TMPD"
  exit "$code"
}
trap on_exit EXIT
trap 'echo; echo "Abgebrochen."; exit 130' INT TERM

# ---------- Eingabe -----------------------------------------------------------
INTERACTIVE=1
if [ ! -t 0 ] || [ "${HH_YES:-0}" = 1 ]; then INTERACTIVE=0; fi

# ask VAR "Frage" "Vorgabe" [pruefer] [opt]   (HH_<VAR> hat Vorrang; opt = darf leer bleiben)
ask() {
  local var=$1 q=$2 def=${3-} chk=${4:-} opt=${5:-} envn="HH_$1" val
  if [ -n "${!envn+x}" ]; then
    val=${!envn}
    if [ -n "$chk" ] && [ -n "$val" ] && ! "$chk" "$val" >&2; then die "Ungueltiger Wert in $envn: $val"; fi
    printf -v "$var" '%s' "$val"; return 0
  fi
  while :; do
    if [ "$INTERACTIVE" = 1 ]; then
      if [ -n "$def" ]; then read -r -p "  $q [$def]: " val || die "Eingabe abgebrochen"; val=${val:-$def}
      else read -r -p "  $q: " val || die "Eingabe abgebrochen"; fi
    else
      val=$def
      [ -n "$val" ] || [ -n "$opt" ] || die "Keine Vorgabe fuer \"$q\". Setze $envn."
    fi
    if [ -z "$val" ] && [ -n "$opt" ]; then printf -v "$var" '%s' ""; return 0; fi
    if [ -z "$val" ]; then echo "  Bitte einen Wert eingeben." >&2; continue; fi
    if [ -n "$chk" ] && ! "$chk" "$val" >&2; then
      if [ "$INTERACTIVE" = 1 ]; then continue; else die "Ungueltiger Wert fuer \"$q\": $val"; fi
    fi
    printf -v "$var" '%s' "$val"; return 0
  done
}

# ---------- Pruefer -----------------------------------------------------------
is_int()  { [[ $1 =~ ^[0-9]+$ ]] || { echo "Bitte eine Zahl eingeben."; return 1; }; }
ip2int()  { local IFS=.; set -- $1; echo $(( ($1<<24) + ($2<<16) + ($3<<8) + $4 )); }
is_ip()   { local o IFS=.; [[ $1 =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || { echo "Keine gueltige IPv4-Adresse."; return 1; }
            for o in $1; do { [ "$o" -le 255 ] && [[ ! $o =~ ^0[0-9] ]]; } || { echo "Keine gueltige IPv4-Adresse (keine fuehrenden Nullen)."; return 1; }; done; }
is_ctid() { is_int "$1" || return 1; [ "$1" -ge 100 ] || { echo "Die ID muss mindestens 100 sein."; return 1; }
            if pct status "$1" >/dev/null 2>&1 || { command -v qm >/dev/null 2>&1 && qm status "$1" >/dev/null 2>&1; }; then echo "ID $1 ist bereits vergeben."; return 1; fi; }
is_host() { [[ $1 =~ ^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$ ]] || { echo "Hostname: nur Buchstaben, Ziffern, Bindestrich."; return 1; }; }
is_url()  { [[ $1 =~ ^https?://[^[:space:]]+$ ]] || { echo "Die Adresse muss mit http:// oder https:// beginnen."; return 1; }; }
is_user() { [[ $1 =~ ^[a-zA-Z0-9._-]{2,32}$ ]] || { echo "Benutzername: 2-32 Zeichen (Buchstaben, Ziffern, . _ -)."; return 1; }; }
is_up()   { [[ $1 =~ ^(https?://)?[A-Za-z0-9._-]+(:[0-9]{1,5})?(/.*)?$ ]] || { echo "Erwartet wird IP:Port, z. B. 192.168.1.20:8096."; return 1; }; }
is_bridge() { [ -d "/sys/class/net/$1" ] || { echo "Bridge $1 existiert auf diesem Host nicht."; return 1; }; }
is_vlan() { is_int "$1" || return 1; if [ "$1" -ge 1 ] && [ "$1" -le 4094 ]; then return 0; fi; echo "VLAN 1-4094."; return 1; }
is_mask() {   # 24 oder 255.255.255.0
  if [[ $1 =~ ^[0-9]+$ ]]; then if [ "$1" -ge 8 ] && [ "$1" -le 30 ]; then return 0; fi; echo "Praefix 8-30 erwartet."; return 1; fi
  is_ip "$1" || return 1
  mask2pfx "$1" >/dev/null || { echo "Keine gueltige Netzmaske."; return 1; }
}
mask2pfx() {
  if [[ $1 =~ ^[0-9]+$ ]]; then echo "$1"; return 0; fi
  local m n=0 i back; m=$(ip2int "$1")
  for i in $(seq 31 -1 0); do if (( (m>>i)&1 )); then n=$((n+1)); else break; fi; done
  back=$(( n==0 ? 0 : (0xFFFFFFFF << (32-n)) & 0xFFFFFFFF ))
  if [ "$back" -eq "$m" ] && [ "$n" -ge 8 ] && [ "$n" -le 30 ]; then echo "$n"; else return 1; fi
}
same_net() {  # ip gw prefix
  local mask=$(( (0xFFFFFFFF << (32-$3)) & 0xFFFFFFFF ))
  [ $(( $(ip2int "$1") & mask )) -eq $(( $(ip2int "$2") & mask )) ]
}
ip_in_configs() { grep -rqsF -e "ip=$1/" -e "ip=$1," "$PVE_CFG_DIR" 2>/dev/null; }
rand_pw() { ( set +o pipefail; openssl rand -base64 48 | tr -dc 'A-Za-z0-9' | head -c 16 ); }

# ---------- Payload -----------------------------------------------------------
extract_payload() {   # nach $TMPD/homehub.tgz
  [ -f "$0" ] || die "Das Script muss als Datei laufen (bash homehub-install.sh), nicht ueber eine Pipe."
  grep -q '^__PAYLOAD__$' "$0" || die "Nutzdaten fehlen - die Datei ist unvollstaendig."
  awk 'f{print} /^__PAYLOAD__$/{f=1}' "$0" | base64 -d > "$TMPD/homehub.tgz" || die "Nutzdaten sind beschaedigt."
  tar tzf "$TMPD/homehub.tgz" >/dev/null || die "Nutzdaten sind beschaedigt."
}

# ---------- Container-Helfer ----------------------------------------------------
cexec() { pct exec "$CTID" -- "$@"; }
cexec_log() { pct exec "$CTID" -- "$@" >>"$LOG" 2>&1; }
health() {  # wartet auf /healthz im Container
  local i
  for i in $(seq 1 30); do
    if pct exec "$CTID" -- node -e "fetch('http://127.0.0.1:$PORT/healthz').then(r=>process.exit(r.ok?0:1)).catch(()=>process.exit(1))" >/dev/null 2>&1; then return 0; fi
    sleep 1
  done
  return 1
}

preflight() {
  [ "$(id -u)" = 0 ] || die "Bitte als root auf dem Proxmox-Host ausfuehren."
  local c; for c in pct pvesm pveam awk base64 tar openssl perl; do command -v "$c" >/dev/null 2>&1 || die "\"$c\" wurde nicht gefunden. Laeuft das Script auf einem Proxmox-VE-Host?"; done
  TMPD=$(mktemp -d); chmod 700 "$TMPD"
}

# =============================================================================
do_update() {
  CTID=$1
  preflight
  pct status "$CTID" >/dev/null 2>&1 || die "Container $CTID existiert nicht."
  if [ "$(pct status "$CTID" | awk '{print $2}')" != running ]; then msg "Starte Container $CTID"; pct start "$CTID"; sleep 5; fi
  cexec test -f /opt/homehub/server.js || die "In Container $CTID ist HomeHub nicht installiert."
  extract_payload
  msg "Aktualisiere HomeHub in Container $CTID (Daten bleiben erhalten)"
  pct push "$CTID" "$TMPD/homehub.tgz" /root/homehub.tgz
  cexec_log bash -c 'set -e; rm -rf /opt/homehub.old; cp -a /opt/homehub /opt/homehub.old; tar xzf /root/homehub.tgz -C /opt/homehub; chown -R root:root /opt/homehub; chmod -R a+rX /opt/homehub; rm -f /root/homehub.tgz; systemctl restart homehub'
  if health; then ok "Portal laeuft wieder (alte Version: /opt/homehub.old im Container)"
  else
    warn "Das Portal startet nicht. Stelle die alte Version wieder her ..."
    cexec_log bash -c 'rm -rf /opt/homehub; mv /opt/homehub.old /opt/homehub; systemctl restart homehub' || true
    die "Update fehlgeschlagen, alte Version wiederhergestellt. Protokoll: $LOG"
  fi
  DONE=1; exit 0
}

case "${1:-}" in
  -h|--help) usage; exit 0;;
  --update)  [ -n "${2:-}" ] || die "Aufruf: --update <CTID>"; do_update "$2";;
  "") ;;
  *) usage; exit 1;;
esac

# =============================================================================
preflight
echo
echo "${B}HomeHub - Installation in einem neuen LXC-Container${N}"
echo "Mit Enter uebernimmst du jeweils den Wert in eckigen Klammern."
[ "$INTERACTIVE" = 1 ] || echo "(Nicht interaktiv: es werden Vorgaben und HH_*-Variablen genutzt.)"
echo

NEXTID=$(pvesh get /cluster/nextid 2>/dev/null | tr -dc '0-9' || true); NEXTID=${NEXTID:-100}

msg "1/4  Container"
ask CTID     "Container-ID" "$NEXTID" is_ctid
if [ -n "${HH_HOSTNAME:-}" ]; then HH_CT_HOSTNAME=$HH_HOSTNAME; fi
ask CT_HOSTNAME "Hostname" "homehub" is_host
STOR_LIST=$(pvesm status --content rootdir 2>/dev/null | awk 'NR>1 && $3=="active"{print $1}' | tr '\n' ' ')
[ -n "$STOR_LIST" ] || die "Kein aktiver Speicher fuer Container-Laufwerke (rootdir) gefunden."
STOR_DEF=$(echo "$STOR_LIST" | tr ' ' '\n' | grep -x 'local-lvm' || true); STOR_DEF=${STOR_DEF:-${STOR_LIST%% *}}
echo "  Verfuegbarer Speicher: $STOR_LIST"
chk_stor() { [[ " $STOR_LIST " == *" $1 "* ]] || { echo "Speicher \"$1\" ist nicht verfuegbar."; return 1; }; }
ask STORAGE  "Speicher fuer das Container-Laufwerk" "$STOR_DEF" chk_stor
ask DISK     "Laufwerksgroesse in GB" "4" is_int
ask RAM      "Arbeitsspeicher in MB" "512" is_int
ask CORES    "CPU-Kerne" "2" is_int

echo; msg "2/4  Netzwerk (feste IP-Adresse)"
BR_DEF=vmbr0; [ -d /sys/class/net/vmbr0 ] || BR_DEF=$(ls /sys/class/net 2>/dev/null | grep -m1 '^vmbr' || echo vmbr0)
ask BRIDGE   "Netzwerk-Bridge" "$BR_DEF" is_bridge
ask VLAN     "VLAN-Tag (leer = keins)" "" is_vlan opt
ask IP       "IP-Adresse des Containers" "" is_ip
ask NETMASK  "Netzmaske (z. B. 255.255.255.0 oder 24)" "255.255.255.0" is_mask
PFX=$(mask2pfx "$NETMASK")
GW_DEF=""; if [[ $IP =~ ^([0-9]+\.[0-9]+\.[0-9]+)\. ]]; then GW_DEF="${BASH_REMATCH[1]}.1"; fi
ask GW       "Gateway (UniFi Dream Machine)" "$GW_DEF" is_ip
same_net "$IP" "$GW" "$PFX" || die "Das Gateway $GW liegt nicht im Netz von $IP/$PFX."
_m=$(( (0xFFFFFFFF << (32-PFX)) & 0xFFFFFFFF )); _ip=$(ip2int "$IP")
if [ $(( _ip & ~_m & 0xFFFFFFFF )) -eq 0 ] || [ $(( _ip | _m )) -eq 4294967295 ]; then die "Die IP $IP ist die Netz- oder Broadcast-Adresse von /$PFX."; fi
ask DNS      "DNS-Server (UniFi Dream Machine)" "$GW" is_ip

msg "Pruefe Netzwerk ..."
[ "$IP" != "$GW" ] || die "IP-Adresse und Gateway sind identisch."
if ip_in_configs "$IP"; then die "Die IP $IP ist bereits in einer Proxmox-Gast-Konfiguration eingetragen."; fi
if ping -c1 -W2 "$IP" >/dev/null 2>&1; then die "Die IP $IP antwortet bereits im Netz. Waehle eine freie Adresse."; fi
ok "$IP ist frei"
if ping -c1 -W2 "$GW" >/dev/null 2>&1; then ok "Gateway $GW erreichbar"
else warn "Gateway $GW antwortet nicht auf Ping (manche Router blocken Ping). Die Installation laeuft weiter."; fi

echo; msg "3/4  Portal"
ask ADMIN      "Admin-Benutzername" "admin" is_user
ask ADMIN_NAME "Anzeigename des Admins" "$ADMIN"
chk_pw() { if [ ${#1} -ge 10 ]; then return 0; fi; echo "Mindestens 10 Zeichen."; return 1; }
ADMIN_LC=$(printf "%s" "$ADMIN" | tr "[:upper:]" "[:lower:]")
GENPW=0
if [ -n "${HH_ADMIN_PASS+x}" ]; then ADMIN_PASS=$HH_ADMIN_PASS; chk_pw "$ADMIN_PASS" >/dev/null || die "HH_ADMIN_PASS ist zu kurz (mind. 10 Zeichen)."
elif [ "$INTERACTIVE" = 1 ]; then
  while :; do
    read -r -s -p "  Admin-Passwort (mind. 10 Zeichen, Enter = zufaelliges Passwort): " ADMIN_PASS; echo
    if [ -z "$ADMIN_PASS" ]; then ADMIN_PASS=$(rand_pw); GENPW=1; break; fi
    chk_pw "$ADMIN_PASS" >&2 || continue
    read -r -s -p "  Passwort wiederholen: " p2; echo
    if [ "$ADMIN_PASS" = "$p2" ]; then break; fi
    echo "  Die Eingaben stimmen nicht ueberein." >&2
  done
else ADMIN_PASS=$(rand_pw); GENPW=1; fi
ask PUBLIC_URL "Oeffentliche Portal-Adresse (leer = Direktzugriff)" "" is_url opt
ask PROXY_IP   "IP des Reverse-Proxys (vertrauenswuerdig; leer = noch keiner)" "" is_ip opt

echo; msg "4/4  Optional: direkte Adressen der Dienste (fuer Statusabfragen und die Proxy-Liste)"
echo "  Format IP:Port, z. B. 192.168.1.20:8096. Leer lassen = spaeter im Portal eintragen."
ask UP_JELLYFIN    "Jellyfin"      "" is_up opt
ask UP_PAPERLESS   "Paperless-ngx" "" is_up opt
ask UP_VAULTWARDEN "Vaultwarden"   "" is_up opt
ask UP_HAUSAI      "Haus-KI"       "" is_up opt
ask UP_RETROHUB    "RetroHub"      "" is_up opt
ask KNX_GW         "KNX-IP-Schnittstelle (IP, leer = ohne KNX)" "" is_ip opt
KNX_PORT=3671; if [ -n "$KNX_GW" ]; then ask KNX_PORT "KNX-Port" "3671" is_int; fi

echo
echo "${B}Zusammenfassung${N}"
cat <<EOF
  Container   $CTID ($CT_HOSTNAME), $CORES Kern(e), $RAM MB RAM, $DISK GB auf $STORAGE
  Netzwerk    $IP/$PFX, Gateway $GW, DNS $DNS, Bridge $BRIDGE${VLAN:+, VLAN $VLAN}
  Admin       $ADMIN
  Proxy-IP    ${PROXY_IP:-(keiner)}
EOF
if [ -n "$PUBLIC_URL" ]; then echo "  Portal      $PUBLIC_URL"; else echo "  Portal      direkt: http://$IP:$PORT"; fi
if [ "$INTERACTIVE" = 1 ]; then
  read -r -p "Jetzt installieren? [J/n] " a; case "${a:-J}" in [jJyY]*) ;; *) echo "Abgebrochen."; exit 0;; esac
fi

# ---------- Vorlage ---------------------------------------------------------------
echo; msg "Debian-Vorlage vorbereiten"
TSTOR_LIST=$(pvesm status --content vztmpl 2>/dev/null | awk 'NR>1 && $3=="active"{print $1}' | tr '\n' ' ')
[ -n "$TSTOR_LIST" ] || die "Kein Speicher fuer Container-Vorlagen (vztmpl) gefunden."
TSTOR=${HH_TEMPLATE_STORAGE:-$(echo "$TSTOR_LIST" | tr ' ' '\n' | grep -x local || true)}; TSTOR=${TSTOR:-${TSTOR_LIST%% *}}
tpl_local() { pveam list "$TSTOR" 2>/dev/null | awk '{print $1}' | sed 's|.*/||' | grep "^$1" | sort -V | tail -n1 || true; }
tpl_avail() { pveam available --section system 2>/dev/null | awk '{print $2}' | grep "^$1" | sort -V | tail -n1 || true; }
TPL=${HH_TEMPLATE:-}
[ -n "$TPL" ] || TPL=$(tpl_local debian-13-standard)          # bevorzugt: bereits geladenes Debian 13
if [ -z "$TPL" ]; then
  pveam update >>"$LOG" 2>&1 || warn "pveam update schlug fehl, nutze vorhandene Liste."
  TPL=$(tpl_avail debian-13-standard)
fi
if [ -z "$TPL" ]; then
  warn "Keine Debian-13-Vorlage gefunden, weiche auf Debian 12 aus."
  TPL=$(tpl_local debian-12-standard); [ -n "$TPL" ] || TPL=$(tpl_avail debian-12-standard)
fi
[ -n "$TPL" ] || die "Keine Debian-Vorlage gefunden (pveam available)."
if ! pveam list "$TSTOR" 2>/dev/null | grep -qF "$TPL"; then
  echo "  Lade $TPL herunter ..."
  pveam download "$TSTOR" "$TPL" >>"$LOG" 2>&1 || die "Download der Vorlage $TPL fehlgeschlagen (Protokoll: $LOG)."
fi
ok "Vorlage $TPL"

# ---------- Container -------------------------------------------------------------
msg "Container $CTID anlegen"
NET0="name=eth0,bridge=$BRIDGE,ip=$IP/$PFX,gw=$GW${VLAN:+,tag=$VLAN}"
CREATED=1
pct create "$CTID" "$TSTOR:vztmpl/$TPL" \
  --hostname "$CT_HOSTNAME" --unprivileged 1 --features nesting=1 --onboot 1 \
  --cores "$CORES" --memory "$RAM" --swap 256 --rootfs "$STORAGE:$DISK" \
  --net0 "$NET0" --nameserver "$DNS" --timezone host \
  --description "HomeHub Portal (installiert mit homehub-install.sh)" >>"$LOG" 2>&1
ok "Container angelegt (unprivilegiert)"
pct start "$CTID" >>"$LOG" 2>&1
msg "Warte auf das Netzwerk im Container"
NETOK=0
for i in $(seq 1 40); do
  if pct exec "$CTID" -- getent hosts deb.debian.org >/dev/null 2>&1; then NETOK=1; break; fi; sleep 2
done
[ "$NETOK" = 1 ] || die "Der Container erreicht das Internet/DNS nicht (Gateway $GW, DNS $DNS). Pruefe die Netzwerkangaben."
ok "Netzwerk im Container funktioniert"

# ---------- Einrichtung im Container ---------------------------------------------
extract_payload
pct push "$CTID" "$TMPD/homehub.tgz" /root/homehub.tgz >>"$LOG" 2>&1
cat > "$TMPD/setup.sh" <<'SETUP_EOF'
#!/usr/bin/env bash
set -Eeuo pipefail
export DEBIAN_FRONTEND=noninteractive LC_ALL=C
apt-get update -qq
apt-get install -y -qq --no-install-recommends nodejs ca-certificates openssl
node -e 'process.exit(+process.versions.node.split(".")[0]>=18?0:1)' || { echo "Node.js >= 18 fehlt (gefunden: $(node -v))"; exit 3; }
id homehub >/dev/null 2>&1 || useradd --system --home-dir /var/lib/homehub --shell /usr/sbin/nologin homehub
install -d -m 755 /opt/homehub
install -d -o homehub -g homehub -m 750 /var/lib/homehub
tar xzf /root/homehub.tgz -C /opt/homehub
chown -R root:root /opt/homehub; chmod -R a+rX /opt/homehub
rm -f /root/homehub.tgz

cat > /etc/systemd/system/homehub.service <<'EOF'
[Unit]
Description=HomeHub Portal
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=homehub
Group=homehub
Environment=NODE_ENV=production
Environment=PORT=8080
Environment=HOST=0.0.0.0
Environment=HOMEHUB_DATA=/var/lib/homehub
ExecStart=/usr/bin/node /opt/homehub/server.js
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF

install -d /etc/systemd/system/homehub.service.d
cat > /etc/systemd/system/homehub.service.d/10-hardening.conf <<'EOF'
[Service]
NoNewPrivileges=yes
ProtectSystem=strict
ReadWritePaths=/var/lib/homehub
ProtectHome=yes
PrivateTmp=yes
PrivateDevices=yes
ProtectKernelTunables=yes
ProtectKernelModules=yes
ProtectControlGroups=yes
RestrictSUIDSGID=yes
EOF

cat > /usr/local/bin/homehub-admin <<'EOF'
#!/bin/sh
# Verwaltung von HomeHub auf der Konsole.  homehub-admin help
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin; export PATH
export HOMEHUB_DATA=/var/lib/homehub
if [ "$(id -u)" != 0 ]; then echo "Bitte als root ausfuehren." >&2; exit 1; fi
runuser -u homehub -- env HOMEHUB_DATA="$HOMEHUB_DATA" /usr/bin/node /opt/homehub/cli.js "$@"
rc=$?
if [ -e "$HOMEHUB_DATA/.restart" ]; then rm -f "$HOMEHUB_DATA/.restart"; systemctl restart homehub; fi
exit $rc
EOF
chmod 755 /usr/local/bin/homehub-admin
test -x /usr/local/bin/homehub-admin || { echo "homehub-admin wurde nicht angelegt"; exit 4; }
systemctl daemon-reload
systemctl enable homehub >/dev/null 2>&1
SETUP_EOF
pct push "$CTID" "$TMPD/setup.sh" /root/hh-setup.sh --perms 0700 >>"$LOG" 2>&1
msg "Installiere Node.js und Portal (dauert etwa eine Minute)"
cexec_log bash /root/hh-setup.sh
cexec_log rm -f /root/hh-setup.sh
ok "Software installiert"

# ---------- Ersteinrichtung ----------------------------------------------------------
msg "Richte Portal und Admin-Konto ein"
HH_J_ADMIN="$ADMIN" HH_J_NAME="$ADMIN_NAME" HH_J_PASS="$ADMIN_PASS" HH_J_PUB="$PUBLIC_URL" HH_J_PROXY="$PROXY_IP" \
HH_J_DIRECT="http://$IP:$PORT" HH_J_KGW="$KNX_GW" HH_J_KPORT="$KNX_PORT" \
HH_J_UJ="$UP_JELLYFIN" HH_J_UP="$UP_PAPERLESS" HH_J_UV="$UP_VAULTWARDEN" HH_J_UH="$UP_HAUSAI" HH_J_UR="$UP_RETROHUB" \
perl -MJSON::PP -e '
  my %e=%ENV; my %up;
  my %m=(jellyfin=>"HH_J_UJ",paperless=>"HH_J_UP",vaultwarden=>"HH_J_UV",hausai=>"HH_J_UH",retrohub=>"HH_J_UR");
  for my $k (keys %m){ $up{$k}=$e{$m{$k}} if length $e{$m{$k}}; }
  my %c=(adminUser=>$e{HH_J_ADMIN},adminName=>$e{HH_J_NAME},adminPassword=>$e{HH_J_PASS},publicUrl=>$e{HH_J_PUB},
    trustedProxy=>$e{HH_J_PROXY},directUrl=>$e{HH_J_DIRECT},upstreams=>\%up);
  if(length $e{HH_J_KGW}){ $c{knxGateway}=$e{HH_J_KGW}; $c{knxPort}=$e{HH_J_KPORT}+0; }
  print JSON::PP->new->canonical->encode(\%c);' > "$TMPD/init.json"
chmod 600 "$TMPD/init.json"
pct push "$CTID" "$TMPD/init.json" /var/lib/homehub/init.json --perms 0600 >>"$LOG" 2>&1
cexec_log chown homehub:homehub /var/lib/homehub/init.json
cexec_log ls -l /usr/local/bin/homehub-admin || die "homehub-admin fehlt im Container (Protokoll: $LOG)."
INIT_OUT=$(pct exec "$CTID" -- /usr/local/bin/homehub-admin init /var/lib/homehub/init.json 2>>"$LOG") || die "Die Ersteinrichtung ist fehlgeschlagen (Protokoll: $LOG)."
RECOVERY=$(printf '%s\n' "$INIT_OUT" | sed -n 's/^RECOVERY_CODE=//p' | head -n1)
[ -n "$RECOVERY" ] || die "Der Notfall-Code wurde nicht erzeugt."
ok "Admin-Konto angelegt"

msg "Starte das Portal"
cexec_log systemctl restart homehub || true
HARD=1
if ! health; then
  warn "Start mit Systemhaertung fehlgeschlagen - versuche es ohne (typisch bei eingeschraenkten Container-Rechten)."
  cexec_log bash -c 'rm -f /etc/systemd/system/homehub.service.d/10-hardening.conf; systemctl daemon-reload; systemctl restart homehub' || true
  HARD=0
  if ! health; then
    cexec journalctl -u homehub -n 20 --no-pager >>"$LOG" 2>&1 || true
    die "Das Portal startet nicht. Details: pct exec $CTID -- journalctl -u homehub"
  fi
fi
ok "Portal antwortet auf Port $PORT"
if command -v curl >/dev/null 2>&1; then
  if curl -fsS -m 5 "http://$IP:$PORT/healthz" >/dev/null 2>&1; then ok "Von diesem Host aus erreichbar"
  else warn "Vom Host aus nicht erreichbar (Firewall/VLAN?). Pruefe das spaeter."; fi
fi
DONE=1

# ---------- Abschluss -----------------------------------------------------------------
echo
echo "${G}${B}HomeHub ist installiert.${N}"
echo
cat <<EOF
${B}Zugang${N}
EOF
if [ -n "$PUBLIC_URL" ]; then echo "  Portal (ueber Reverse-Proxy)  $PUBLIC_URL"; fi
cat <<EOF
  Direkt (HTTP)                 http://$IP:$PORT
  Notfall-Anmeldung             http://$IP:$PORT/notfall
  Admin (Login)                 $ADMIN_LC
EOF
if [ "$GENPW" = 1 ]; then echo "  Passwort                $ADMIN_PASS   ${Y}(wird nur jetzt angezeigt, bitte notieren)${N}"; fi
cat <<EOF

${B}Notfall-Code (wird nur jetzt angezeigt, bitte sicher aufbewahren)${N}
  $RECOVERY
  Er ersetzt bei Ausfall des Passworts die Anmeldung. Neuer Code: pct exec $CTID -- /usr/local/bin/homehub-admin new-code

${B}DNS und Reverse-Proxy${N}
  Es wurden keine Hostnamen festgelegt. Eigene DNS-Eintraege und Proxy-Ziele
  kannst du nach Bedarf in deiner DNS- und Proxy-Konfiguration einrichten.
  Oeffentliche App-Adressen legst du nach der Installation unter Anwendungen fest.
EOF
pct exec "$CTID" -- /usr/local/bin/homehub-admin export-proxy 2>>"$LOG" | sed 's/^/  /' || true
cat <<EOF

${B}Wichtig fuer den Reverse-Proxy${N}
  - Eingebettete Seiten brauchen, dass der Proxy X-Frame-Options und frame-ancestors entfernt.
  - Der Proxy muss X-Forwarded-Proto und X-Forwarded-For setzen.
  - Proxy-IP im Portal: ${PROXY_IP:-noch nicht gesetzt (pct exec $CTID -- /usr/local/bin/homehub-admin set-proxy IP)}
  - Vaultwarden funktioniert nur ueber HTTPS.
EOF
[ "$HARD" = 1 ] || echo "  - Der Dienst laeuft ohne systemd-Haertung (eingeschraenkte Container-Rechte)."
cat <<EOF

${B}Verwaltung${N}
  Konsole im Container    pct enter $CTID    ->  homehub-admin help
  Passwort zuruecksetzen  pct exec $CTID -- /usr/local/bin/homehub-admin reset-password BENUTZERNAME
  Aktualisieren           bash $(basename "$0") --update $CTID
  Protokoll der Installation: $LOG
EOF
exit 0
__PAYLOAD__

